func extractTitleAndDescription(htmlContent []byte) (string, string) {
	html := string(htmlContent)

	var title, description string

	// Extract title
	titleRegex := regexp.MustCompile(`(?i)<title[^>]*>([^<]*)</title>`)
	titleMatches := titleRegex.FindStringSubmatch(html)
	if len(titleMatches) > 1 {
		title = strings.TrimSpace(titleMatches[1])
	}

	// Extract meta description (standard)
	descRegex := regexp.MustCompile(`(?i)<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']`)
	descMatches := descRegex.FindStringSubmatch(html)
	if len(descMatches) > 1 {
		description = strings.TrimSpace(descMatches[1])
	}

	// Try alternate format: content before name
	if description == "" {
		descRegex2 := regexp.MustCompile(`(?i)<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']`)
		descMatches2 := descRegex2.FindStringSubmatch(html)
		if len(descMatches2) > 1 {
			description = strings.TrimSpace(descMatches2[1])
		}
	}

	// Try og:description as fallback
	if description == "" {
		ogDescRegex := regexp.MustCompile(`(?i)<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']`)
		ogDescMatches := ogDescRegex.FindStringSubmatch(html)
		if len(ogDescMatches) > 1 {
			description = strings.TrimSpace(ogDescMatches[1])
		}
	}

	return title, description
}

