		}
	}

	return false
}

// validateAndResolveURL validates the URL and ensures it doesn't point to private IPs
func validateAndResolveURL(rawURL string) (*url.URL, error) {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return nil, errors.New("invalid URL format")
	}

	// Only allow http and https schemes
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return nil, errors.New("only HTTP/HTTPS URLs are allowed")
	}

	// Ensure host is not empty
	if parsedURL.Host == "" {
		return nil, errors.New("URL must have a host")
	}

	// Extract hostname (without port)
	hostname := parsedURL.Hostname()
	if hostname == "" {
		return nil, errors.New("URL must have a valid hostname")
	}

	// Block localhost variations
	lowerHost := strings.ToLower(hostname)
	if lowerHost == "localhost" || strings.HasSuffix(lowerHost, ".localhost") {
		return nil, errors.New("localhost URLs are not allowed")
	}

	// Resolve the hostname to IP addresses
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
